static boolean hasUnclosedExecutor(Runnable codeUnderTest, long checkAfterMs) throws InterruptedException {
    codeUnderTest.run();
    Thread.sleep(checkAfterMs);
    return Thread.getAllStackTraces().keySet().stream().anyMatch(t -> t.getName().startsWith("pool-") && t.isAlive());
}
System.out.println(hasUnclosedExecutor(() -> {
    ExecutorService pool = Executors.newFixedThreadPool(2);
    pool.submit(() -> {});
    pool.shutdown();
    try { pool.awaitTermination(2, TimeUnit.SECONDS); } catch (Exception e) {}
}, 100)); // false - poprawnie zamkniete

