class AntiPatternCatalog {
    static void dlugaSekcjaKrytyczna() { Object lock = new Object(); synchronized (lock) { long s=0; for (int i=0;i<100_000;i++) s+=i; } System.out.println("ZLE: kosztowne obliczenie w synchronized"); }
    static void brakFinally() { ReentrantLock lock = new ReentrantLock(); lock.lock(); System.out.println("praca"); lock.unlock(); System.out.println("ZLE: unlock() poza finally - przy wyjatku NIGDY by sie nie wykonal"); }
    static void brakShutdown() { ExecutorService pool = Executors.newFixedThreadPool(2); pool.submit(() -> {}); System.out.println("ZLE: brak shutdown() - w prawdziwym programie JVM by 'wisial'"); pool.shutdown(); pool.awaitTermination(2, TimeUnit.SECONDS); }
}
AntiPatternCatalog.dlugaSekcjaKrytyczna();
AntiPatternCatalog.brakFinally();
AntiPatternCatalog.brakShutdown();

