interface ExecutorServiceUsage { boolean hasShutdown(); boolean hasAwaitTermination(); boolean hasShutdownNowFallback(); }
static List<String> reviewCode(ExecutorServiceUsage usage) {
    List<String> problemy = new ArrayList<>();
    if (!usage.hasShutdown()) problemy.add("BRAK shutdown()");
    if (!usage.hasAwaitTermination()) problemy.add("BRAK awaitTermination()");
    if (!usage.hasShutdownNowFallback()) problemy.add("BRAK shutdownNow() jako fallback");
    return problemy;
}
ExecutorServiceUsage poprawne = new ExecutorServiceUsage() { public boolean hasShutdown() { return true; } public boolean hasAwaitTermination() { return true; } public boolean hasShutdownNowFallback() { return true; } };
System.out.println(reviewCode(poprawne));

class CriticalSectionProfiler {
    Map<String, Long> lacznyCzas = new ConcurrentHashMap<>();
    <T> T profile(String nazwa, Lock lock, Supplier<T> action) {
        lock.lock();
        long t0 = System.nanoTime();
        try { return action.get(); } finally { lock.unlock(); lacznyCzas.merge(nazwa, System.nanoTime()-t0, Long::sum); }
    }
}
CriticalSectionProfiler profiler = new CriticalSectionProfiler();
ReentrantLock lock = new ReentrantLock();
profiler.profile("szybka", lock, () -> 1);
profiler.profile("wolna", lock, () -> { long s=0; for (int i=0;i<1_000_000;i++) s+=i; return s; });
System.out.println(profiler.lacznyCzas);

