class ThreadingRulesLinter {
    List<String> lint(String kod) {
        List<String> problemy = new ArrayList<>();
        if (kod.contains("for") && kod.contains("new Thread(")) problemy.add("mozliwe tworzenie watkow w petli (Zasada 1)");
        if (kod.contains("lock()") && !kod.contains("finally")) problemy.add("brak finally po lock() (Zasada 5)");
        if (kod.contains("ExecutorService") && !kod.contains("shutdown")) problemy.add("brak shutdown() (Zasada 6)");
        return problemy;
    }
}
ThreadingRulesLinter linter = new ThreadingRulesLinter();
System.out.println(linter.lint("ExecutorService pool = Executors.newFixedThreadPool(2); pool.submit(() -> {}); pool.shutdown();"));
System.out.println(linter.lint("for (int i=0;i<10;i++) { new Thread(() -> {}).start(); }"));

record ImmutableCustomerRequest(int id, String typ) {}
class SafeResource { ReentrantLock lock = new ReentrantLock(); <T> T withLock(Supplier<T> a) { lock.lock(); try { return a.get(); } finally { lock.unlock(); } } }
BlockingQueue<ImmutableCustomerRequest> kolejka = new ArrayBlockingQueue<>(50);
for (int i=1;i<=50;i++) kolejka.put(new ImmutableCustomerRequest(i, i%2==0?"VIP":"zwykly"));
Map<String,Integer> statystyki = new HashMap<>();
SafeResource resource = new SafeResource();
ExecutorService pool = Executors.newFixedThreadPool(4);
for (int i=0;i<50;i++) pool.submit(() -> {
    try {
        ImmutableCustomerRequest req = kolejka.poll(1, TimeUnit.SECONDS);
        if (req != null) resource.withLock(() -> { statystyki.merge(req.typ(), 1, Integer::sum); return null; });
    } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
});
pool.shutdown(); pool.awaitTermination(5, TimeUnit.SECONDS);
System.out.println(statystyki);
